function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let minPathValue = Infinity;
    let minPath;

    function dfs(row, col, pathLength, currentPath) {
        if (pathLength === k) {
            const currentValue = grid[row][col];
            if (currentValue < minPathValue) {
                minPathValue = currentValue;
                minPath = [...currentPath];
            }
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                dfs(newRow, newCol, pathLength + 1, [...currentPath, grid[newRow][newCol]]);
            }
        }
    }

    for (let row = 0; row < N; row++) {
        for (let col = 0; col < N; col++) {
            dfs(row, col, 1, [grid[row][col]]);
        }
    }

    return minPath;
}

