function find_min_diff(arr, n) {
    arr.sort((a, b) => a - b); // Sort the array to make finding the minimum difference easier
    let min_diff = Infinity; // Initialize min_diff with infinity

    for (let i = 0; i < n - 1; i++) {
        let current_diff = arr[i + 1] - arr[i]; // Calculate the difference between consecutive elements
        if (current_diff < min_diff) {
            min_diff = current_diff; // Update min_diff if a smaller difference is found
        }
    }

    return min_diff;
}

