function prime_length(string) {
  const length = string.length;

  function isPrime(num) {
    if (num <= 1) return false;
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) return false;
    }
    return true;
  }

  return isPrime(length);
}

function pack_consecutive_duplicates(list1) {
  let result = [];
  let currentSubarray = [list1[0]];

  for (let i = 1; i < list1.length; i++) {
    if (list1[i] === currentSubarray[currentSubarray.length - 1]) {
      currentSubarray.push(list1[i]);
    } else {
      result.push(currentSubarray);
      currentSubarray = [list1[i]];
    }
  }

  result.push(currentSubarray);

  return result;
}

function sum_negativenum(nums) {
  return nums.filter(num => num < 0).reduce((acc, curr) => acc + curr, 0);
}

